package main

import (
	"database/sql"
	"fmt"
	"path/filepath"

	_ "github.com/mattn/go-sqlite3"
)

type Ledger struct {
	db *sql.DB
}

type TxState struct {
	ID      int64
	Key     string
	Account string
	Amount  int
	Status  string
}

func NewLedger(dataDir string) *Ledger {
	db, err := sql.Open("sqlite3", "file:"+filepath.Join(dataDir, "ledger.db")+"?_journal_mode=WAL&_busy_timeout=5000")
	if err != nil {
		panic(err)
	}
	// A single connection avoids SQLITE_BUSY contention inside this service while
	// still allowing SQLite itself to provide durable, serialized transactions.
	db.SetMaxOpenConns(1)
	if err := db.Ping(); err != nil {
		panic(err)
	}
	if err := initialize(db); err != nil {
		panic(err)
	}
	return &Ledger{db: db}
}

func initialize(db *sql.DB) error {
	statements := []string{
		`CREATE TABLE IF NOT EXISTS transactions (
			id INTEGER PRIMARY KEY AUTOINCREMENT,
			key TEXT NOT NULL,
			account TEXT NOT NULL,
			amount INTEGER NOT NULL,
			status TEXT NOT NULL DEFAULT 'pending'
		)`,
		`CREATE TABLE IF NOT EXISTS accounts (
			name TEXT PRIMARY KEY,
			balance INTEGER NOT NULL DEFAULT 0
		)`,
		// Clean up rows created by the old, non-unique schema. Prefer a completed
		// row over a duplicate pending row so recovery cannot repeat that debit.
		`DELETE FROM transactions
		 WHERE status = 'pending'
		   AND EXISTS (SELECT 1 FROM transactions completed
		               WHERE completed.key = transactions.key
		                 AND completed.status = 'completed')`,
		`DELETE FROM transactions
		 WHERE id NOT IN (SELECT MIN(id) FROM transactions GROUP BY key)`,
		`CREATE UNIQUE INDEX IF NOT EXISTS idx_transactions_key ON transactions(key)`,
	}
	for _, stmt := range statements {
		if _, err := db.Exec(stmt); err != nil {
			return fmt.Errorf("initialize ledger: %w", err)
		}
	}
	return nil
}

func (l *Ledger) Recover() {
	rows, err := l.db.Query("SELECT id, key, account, amount FROM transactions WHERE status = 'pending'")
	if err != nil {
		return
	}
	var recovered []TxRequest
	for rows.Next() {
		var req TxRequest
		if err := rows.Scan(&req.ID, &req.Key, &req.Account, &req.Amount); err != nil {
			continue
		}
		recovered = append(recovered, req)
	}
	rows.Close()
	for _, req := range recovered {
		l.processOne(req)
	}
}

// CreateOrGet atomically reserves a key. A repeated POST therefore always gets
// the same transaction, whether it arrives while the first is running or after
// a process restart.
func (l *Ledger) CreateOrGet(key, account string, amount int) (TxState, error) {
	_, err := l.db.Exec(
		"INSERT INTO transactions(key, account, amount, status) VALUES(?, ?, ?, 'pending') ON CONFLICT(key) DO NOTHING",
		key, account, amount,
	)
	if err != nil {
		return TxState{}, fmt.Errorf("create transaction: %w", err)
	}

	var tx TxState
	err = l.db.QueryRow(
		"SELECT id, key, account, amount, status FROM transactions WHERE key = ?", key,
	).Scan(&tx.ID, &tx.Key, &tx.Account, &tx.Amount, &tx.Status)
	if err != nil {
		return TxState{}, fmt.Errorf("load transaction: %w", err)
	}
	return tx, nil
}

func (l *Ledger) ProcessLoop(ch <-chan TxRequest) {
	for req := range ch {
		l.processOne(req)
	}
}

func (l *Ledger) processOne(req TxRequest) {
	// The Done channel is signaled even on an error so an HTTP caller cannot
	// hang; it checks the persisted status before returning success.
	if req.Done != nil {
		defer func() { req.Done <- struct{}{} }()
	}

	tx, err := l.db.Begin()
	if err != nil {
		return
	}

	var status string
	err = tx.QueryRow("SELECT status FROM transactions WHERE id = ?", req.ID).Scan(&status)
	if err != nil || status != "pending" {
		tx.Rollback()
		return
	}

	_, err = tx.Exec(
		`INSERT INTO accounts(name, balance) VALUES(?, -?)
		 ON CONFLICT(name) DO UPDATE SET balance = balance - ?`,
		req.Account, req.Amount, req.Amount,
	)
	if err != nil {
		tx.Rollback()
		return
	}

	result, err := tx.Exec(
		"UPDATE transactions SET status = 'completed' WHERE id = ? AND status = 'pending'", req.ID,
	)
	if err != nil {
		tx.Rollback()
		return
	}
	if affected, err := result.RowsAffected(); err != nil || affected != 1 {
		tx.Rollback()
		return
	}

	// The debit and status transition become visible together. A crash before
	// Commit leaves the row pending and harmless; after Commit it is completed
	// and can never be processed again.
	tx.Commit()
}

func (l *Ledger) GetTransaction(key string) *Transaction {
	var tx Transaction
	err := l.db.QueryRow(
		"SELECT key, account, amount, status FROM transactions WHERE key = ?", key,
	).Scan(&tx.Key, &tx.Account, &tx.Amount, &tx.Status)
	if err != nil {
		return nil
	}
	return &tx
}

func (l *Ledger) GetAccount(name string) (int, bool) {
	var balance int
	err := l.db.QueryRow("SELECT balance FROM accounts WHERE name = ?", name).Scan(&balance)
	if err != nil {
		return 0, false
	}
	return balance, true
}
