type Handler struct {
	ledger *Ledger
	queue  chan<- TxRequest
}

func (h *Handler) CreateTx(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	var req struct {
		Key     string `json:"key"`
		Account string `json:"account"`
		Amount  int    `json:"amount"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}

	state, err := h.ledger.CreateOrGet(req.Key, req.Account, req.Amount)
	if err != nil {
		http.Error(w, "internal server error", http.StatusInternalServerError)
		return
	}
	if state.Status == "pending" {
		done := make(chan struct{})
		h.queue <- TxRequest{ID: state.ID, Key: state.Key, Account: state.Account, Amount: state.Amount, Done: done}
		<-done
